CREATE TABLE IF NOT EXISTS issues(id INT PRIMARY KEY AUTO_INCREMENT,family_id INT NULL,family_name VARCHAR(200) NOT NULL,target_type VARCHAR(20) NOT NULL,target_id INT NOT NULL,subject_email VARCHAR(254) NOT NULL,original_email VARCHAR(254) NOT NULL,title VARCHAR(200) NOT NULL,note VARCHAR(1000) NOT NULL DEFAULT '',status VARCHAR(20) NOT NULL DEFAULT 'todo',revision INT NOT NULL DEFAULT 0,created_at VARCHAR(30) NOT NULL,updated_at VARCHAR(30) NOT NULL,done_at VARCHAR(30) NOT NULL DEFAULT '',resolution VARCHAR(20) NOT NULL DEFAULT '',resolution_email VARCHAR(254) NOT NULL DEFAULT '',resolution_note VARCHAR(1000) NOT NULL DEFAULT '',FOREIGN KEY(family_id) REFERENCES families(id) ON DELETE SET NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;
CREATE TABLE IF NOT EXISTS audit_events(id INT PRIMARY KEY AUTO_INCREMENT,action VARCHAR(200) NOT NULL,actor VARCHAR(200) NOT NULL,message LONGTEXT NOT NULL,details LONGTEXT NOT NULL,created_at VARCHAR(30) NOT NULL) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;
